const fs = require('fs');

function main() {
  let data;
  try {
    data = fs.readFileSync(0, 'utf8');
  } catch (e) {
    data = fs.readFileSync('/dev/stdin', 'utf8');
  }
  const lines = data.split('\n').map(s => s.trim()).filter(s => s.length > 0);
  if (lines.length === 0) {
    process.stdout.write('ok\n');
    return;
  }
  const n = parseInt(lines[0], 10);

  // Conjunto de strings completas já vistas (detecta ocorrência inteiramente
  // dentro de S_a ou de S_b, i.e., posição 0 ou 10 da concatenação).
  const seen = new Set();

  // prefixSets[L]: prefixos de comprimento L das strings anteriores
  // suffixSets[L]: sufixos de comprimento L das strings anteriores
  const prefixSets = new Array(10);
  const suffixSets = new Array(10);
  for (let L = 1; L <= 9; L++) {
    prefixSets[L] = new Set();
    suffixSets[L] = new Set();
  }

  const count = Math.min(n, lines.length - 1);
  for (let idx = 1; idx <= count; idx++) {
    const S = lines[idx];

    // Pré-computa prefixos e sufixos de todos os comprimentos 1..9
    const pref = new Array(10);
    const suf = new Array(10);
    for (let L = 1; L <= 9; L++) {
      pref[L] = S.slice(0, L);
      suf[L] = S.slice(10 - L);
    }

    // Verifica se S_k é substring de alguma concatenação S_a S_b (a, b < k).
    // Ocorrência na posição i (1..9): S_k = sufixo de S_a (comp. 10-i) + prefixo de S_b (comp. i)
    // i = 0 ou i = 10  <=>  S_k igual a alguma string anterior.
    let bad = seen.has(S);
    if (!bad) {
      for (let j = 1; j <= 9; j++) {
        // parte de S_b tem comprimento j; parte de S_a tem comprimento 10-j
        if (suffixSets[10 - j].has(pref[10 - j]) && prefixSets[j].has(suf[j])) {
          bad = true;
          break;
        }
      }
    }

    if (bad) {
      process.stdout.write(S + '\n');
      return;
    }

    // Insere a string atual nas estruturas para as próximas verificações
    seen.add(S);
    for (let L = 1; L <= 9; L++) {
      prefixSets[L].add(pref[L]);
      suffixSets[L].add(suf[L]);
    }
  }

  process.stdout.write('ok\n');
}

main();
